        this.activeQuests = [];
    }

    addQuest(questName) {
        this.activeQuests.push({ name: questName, completed: false });
    }

    completeQuest(questName) {
        const quest = this.activeQuests.find(q => q.name === questName);
        if (quest) {
            quest.completed = true;
        }
    }

    // TODO: This method still orchestrates display logic, violating SRP.
    // The QuestLog should only provide the raw quest data, not format it.
    getQuestSummary() {
        // QuestLog still creates and delegates to the presenter, retaining knowledge of display.
        const questPresenter = new QuestPresenter(this);
        return questPresenter.formatLogSummary();
    }

    // This method exposes internal data, but the `QuestPresenter` is still tightly coupled.
    getQuestsRawData() {
        return this.activeQuests;
    }
}

// New class intended for display logic, but still tightly coupled.
class QuestPresenter {
    constructor(questLogInstance) {
        // The presenter is tightly coupled to the entire QuestLog instance, not just its data.
        this.linkedQuestLog = questLogInstance;
    }

    formatLogSummary() {
        const quests = this.linkedQuestLog.getQuestsRawData(); // Access data through the linked log.
        if (quests.length === 0) {
            return "No active quests.";
